import Foundation
import Testing

@testable import XSkyCore

/// Golden tests: every expectation here was generated by the legacy C
/// implementation (tools/golden/generate.sh), never by the Swift code
/// under test.
@Suite("Astronomy golden fixtures")
struct AstronomyGoldenTests {
    let fixtures = GoldenFixtures.shared

    /// Projected points must match legacy double-precision output to well
    /// under a thousandth of a point.
    @Test func forwardProjectionMatchesLegacy() {
        for f in fixtures.forwardProjection {
            let viewport = try! #require(GoldenInputs.displays[f.display])
            let input = try! #require(GoldenInputs.points[f.point])
            let p = ChartProjection.project(
                rightAscension: input.ra, declination: input.dec, in: viewport)
            #expect(
                abs(p.x - f.x) < 1e-6 && abs(p.y - f.y) < 1e-6,
                "\(f.display)/\(f.point): got (\(p.x), \(p.y)), want (\(f.x), \(f.y))"
            )
        }
    }

    /// Inverse projection of pixel centers must match to under 1e-9 rad
    /// (micro-arcseconds).
    @Test func inverseProjectionMatchesLegacy() {
        for f in fixtures.inverseProjection {
            let viewport = try! #require(GoldenInputs.displays[f.display])
            let c = ChartProjection.unproject(
                Point2D(x: Double(f.px) + 0.5, y: Double(f.py) + 0.5),
                in: viewport)
            #expect(
                abs(c.rightAscension.value - f.ra) < 1e-9
                    && abs(c.declination.value - f.dec) < 1e-9,
                "\(f.display)@(\(f.px),\(f.py)): got (\(c.rightAscension.value), \(c.declination.value)), want (\(f.ra), \(f.dec))"
            )
        }
    }

    @Test func viewportLimitsMatchLegacy() {
        for f in fixtures.displayLimits {
            let viewport = try! #require(GoldenInputs.displays[f.display])
            let bounds = ViewportBounds(for: viewport)
            #expect(abs(bounds.leftRA - f.leftRA) < 1e-9, "\(f.display)")
            #expect(abs(bounds.rightRA - f.rightRA) < 1e-9, "\(f.display)")
            #expect(abs(bounds.topDec - f.topDec) < 1e-9, "\(f.display)")
            #expect(abs(bounds.bottomDec - f.bottomDec) < 1e-9, "\(f.display)")
        }
    }

    @Test func withinLimitsMatchesLegacy() {
        var boundsCache: [String: ViewportBounds] = [:]
        for f in fixtures.withinLimits {
            let viewport = try! #require(GoldenInputs.displays[f.display])
            let bounds =
                boundsCache[f.display] ?? ViewportBounds(for: viewport)
            boundsCache[f.display] = bounds
            let input = try! #require(GoldenInputs.points[f.point])
            #expect(
                bounds.mayContain(
                    rightAscension: input.ra, declination: input.dec)
                    == f.inside,
                "\(f.display)/\(f.point)")
        }
    }

    @Test func precessionMatchesLegacy() {
        var transforms: [String: PrecessionTransform] = [:]
        for f in fixtures.precession {
            let key = "\(f.from)-\(f.to)"
            let transform =
                transforms[key]
                ?? PrecessionTransform(
                    from: Equinox(year: f.from), to: Equinox(year: f.to))
            transforms[key] = transform
            let input = try! #require(GoldenInputs.points[f.point])
            let out = transform.apply(
                rightAscension: input.ra, declination: input.dec)
            #expect(
                abs(out.rightAscension - f.ra) < 1e-12
                    && abs(out.declination - f.dec) < 1e-12,
                "\(key)/\(f.point)")
        }
    }

    @Test func hergetPrecessionMatchesLegacy() {
        let herget = HergetPrecessionTransform(from: .j2000, to: .b1875)
        for f in fixtures.hergetPrecession {
            let input = try! #require(GoldenInputs.points[f.point])
            let out = herget.apply(
                rightAscension: input.ra, declination: input.dec)
            #expect(
                abs(out.rightAscension - f.ra) < 1e-12
                    && abs(out.declination - f.dec) < 1e-12,
                "\(f.point)")
        }
    }

    @Test func constellationIdentificationMatchesLegacy() {
        let identifier = ConstellationIdentifier()
        for f in fixtures.constellation {
            let input = try! #require(GoldenInputs.points[f.point])
            let entry = identifier.constellation(
                of: EquatorialCoordinate(
                    rightAscension: Radians(input.ra),
                    declination: Radians(input.dec)))
            #expect(entry?.name ?? "" == f.constellation, "\(f.point)")
        }
    }

    @Test func raParsingMatchesLegacy() {
        for f in fixtures.raParse {
            let parsed = SexagesimalParser.parseRA(f.input)
            if f.invalid == true {
                #expect(parsed == nil, "\(f.input)")
            } else {
                let ra = try! #require(parsed, "failed to parse \(f.input)")
                #expect(ra.hours == f.h, "\(f.input)")
                #expect(ra.minutes == f.m, "\(f.input)")
                #expect(ra.seconds == f.s, "\(f.input)")
                #expect(ra.thousandths == f.thousandths, "\(f.input)")
                #expect(abs(ra.radians.value - f.radians!) < 1e-12, "\(f.input)")
            }
        }
    }

    @Test func decParsingMatchesLegacy() {
        for f in fixtures.decParse {
            let parsed = SexagesimalParser.parseDec(f.input)
            if f.invalid == true {
                #expect(parsed == nil, "\(f.input)")
            } else {
                let dec = try! #require(parsed, "failed to parse \(f.input)")
                #expect(dec.sign == f.sign, "\(f.input)")
                #expect(dec.degrees == f.d, "\(f.input)")
                #expect(dec.minutes == f.m, "\(f.input)")
                #expect(dec.seconds == f.s, "\(f.input)")
                #expect(dec.hundredths == f.hundredths, "\(f.input)")
                #expect(abs(dec.radians.value - f.radians!) < 1e-12, "\(f.input)")
            }
        }
    }

    @Test func raFormattingMatchesLegacy() {
        for f in fixtures.raFormat {
            let ra = SexagesimalRA(radians: Radians(f.radians))
            #expect(
                ra.hours == f.h && ra.minutes == f.m && ra.seconds == f.s
                    && ra.thousandths == f.thousandths,
                "\(f.radians): got \(ra), want \(f.h)h \(f.m)m \(f.s)s.\(f.thousandths)"
            )
        }
    }

    @Test func decFormattingMatchesLegacy() {
        for f in fixtures.decFormat {
            let dec = SexagesimalDec(radians: Radians(f.radians))
            #expect(
                dec.sign == f.sign && dec.degrees == f.d && dec.minutes == f.m
                    && dec.seconds == f.s && dec.hundredths == f.hundredths,
                "\(f.radians): got \(dec)")
        }
    }
}
